<template>
<div class="app-container" v-loading="loading"><el-alert title="保存只更新外观草稿。发布或恢复会创建新版本；不会恢复已下架文章和产品。轮播采用可横向滚动的图片组。" :closable="false" style="margin-bottom:16px"/>
<el-form v-if="cfg" label-width="110px" @submit.prevent>
<el-row :gutter="20"><el-col :md="12" :xs="24"><el-form-item label="站点名称"><el-input v-model="cfg.siteName" maxlength="60"/></el-form-item></el-col><el-col :md="12" :xs="24"><el-form-item label="模板"><el-select v-model="cfg.theme"><el-option label="企业官网" value="business"/><el-option label="资讯门户" value="editorial"/></el-select></el-form-item></el-col></el-row>
<el-form-item label="站点简介"><el-input v-model="cfg.slogan" maxlength="200"/></el-form-item>
<el-row :gutter="20"><el-col :md="12" :xs="24"><el-form-item label="配色"><el-select v-model="cfg.palette"><el-option label="暖灰" value="earth"/><el-option label="海蓝" value="ocean"/><el-option label="森林" value="forest"/></el-select></el-form-item></el-col><el-col :md="12" :xs="24"><el-form-item label="页面密度"><el-select v-model="cfg.density"><el-option label="标准" value="normal"/><el-option label="紧凑" value="compact"/></el-select></el-form-item></el-col></el-row>
<el-form-item label="站点Logo"><AssetPicker v-model="cfg.logoAssetId"/></el-form-item><el-form-item label="站点图标"><AssetPicker v-model="cfg.iconAssetId"/></el-form-item><el-form-item label="字号"><el-select v-model="cfg.fontScale"><el-option label="标准" value="standard"/><el-option label="加大" value="large"/></el-select></el-form-item><el-form-item label="内容宽度"><el-select v-model="cfg.frameWidth"><el-option label="标准" value="normal"/><el-option label="宽版" value="wide"/></el-select></el-form-item><el-form-item label="圆角"><el-select v-model="cfg.radius"><el-option label="直角" value="square"/><el-option label="柔和" value="soft"/></el-select></el-form-item><el-form-item label="页脚文字"><el-input v-model="cfg.footer" maxlength="500"/></el-form-item><el-form-item label="联系电话"><el-input v-model="cfg.phone" maxlength="60"/></el-form-item><el-form-item label="联系邮箱"><el-input v-model="cfg.email" maxlength="100"/></el-form-item>
<el-divider content-position="left">导航（最多12项；内部内容填写内容ID，外链填写HTTPS地址）</el-divider><el-table :data="cfg.navigation"><el-table-column label="位置" width="120"><template #default="s"><el-select v-model="s.row.placement"><el-option label="页头" value="header"/><el-option label="页脚" value="footer"/></el-select></template></el-table-column><el-table-column label="名称" min-width="130"><template #default="s"><el-input v-model="s.row.label" maxlength="30"/></template></el-table-column><el-table-column label="内容ID（0表示网址）" width="180"><template #default="s"><el-input-number v-model="s.row.contentId" :min="0" :precision="0" controls-position="right" style="width:150px"/></template></el-table-column><el-table-column label="网址" min-width="200"><template #default="s"><el-input v-model="s.row.url" :disabled="s.row.contentId>0" placeholder="/news 或 https://…" @change="()=>{}"/></template></el-table-column><el-table-column label="排序" width="150"><template #default="s"><el-button link @click="move(cfg.navigation,s.$index,-1)">上移</el-button><el-button link @click="move(cfg.navigation,s.$index,1)">下移</el-button><el-button link type="danger" @click="cfg.navigation.splice(s.$index,1)">移除</el-button></template></el-table-column></el-table><el-button :disabled="cfg.navigation.length>=12" style="margin:12px 0" @click="cfg.navigation.push({label:'',contentId:0,url:'',placement:'header'})">添加导航</el-button>
<el-divider content-position="left">轮播图片（最多5项；内容ID留0时只展示图片）</el-divider><div v-for="(b,i) in cfg.banners" :key="i" class="banner"><el-input v-model="b.title" maxlength="100" placeholder="图片说明"/><AssetPicker v-model="b.assetId"/><el-input-number v-model="b.contentId" :min="0" :precision="0" controls-position="right"/><el-switch v-model="b.enabled"/><el-button @click="move(cfg.banners,i,-1)">上移</el-button><el-button @click="move(cfg.banners,i,1)">下移</el-button><el-button type="danger" plain @click="cfg.banners.splice(i,1)">移除</el-button></div><el-button :disabled="cfg.banners.length>=5" @click="cfg.banners.push({title:'',assetId:0,contentId:0,enabled:true})">添加轮播</el-button>
<el-divider content-position="left">首页区块（栏目ID为0时读取该类型全部已发布内容）</el-divider><el-table :data="cfg.blocks"><el-table-column label="类型" width="130"><template #default="s">{{kinds[s.row.kind]}}</template></el-table-column><el-table-column label="启用" width="100"><template #default="s"><el-switch v-model="s.row.enabled"/></template></el-table-column><el-table-column label="栏目ID" min-width="150"><template #default="s"><el-input-number v-model="s.row.channelId" :min="0" :precision="0" :disabled="s.row.kind==='PAGE'" controls-position="right"/></template></el-table-column><el-table-column label="条数" width="180"><template #default="s"><el-input-number v-model="s.row.count" :min="1" :max="12" :precision="0"/></template></el-table-column><el-table-column label="排序" width="150"><template #default="s"><el-button link @click="move(cfg.blocks,s.$index,-1)">上移</el-button><el-button link @click="move(cfg.blocks,s.$index,1)">下移</el-button></template></el-table-column></el-table>
<div class="actions"><el-button v-if="can('edit')" type="primary" :loading="busy" @click="save">保存草稿</el-button><el-button v-if="can('query')" :disabled="busy" @click="preview">预览已保存草稿</el-button><el-button v-if="can('publish')" type="success" :loading="busy" @click="publish(0)">发布已保存草稿</el-button><el-button @click="load">重新读取</el-button></div>
</el-form><el-divider content-position="left">站点巡检</el-divider><el-alert title="每次检查20篇已标记发布内容和当前外观；不探测外站，媒体直链仅标记待核验。" :closable="false"/><el-button v-if="canInspect" style="margin:12px 0" :loading="inspecting" @click="inspect">检查当前页</el-button><el-button :disabled="inspectionPage<=1||inspecting" @click="inspectionPage--;inspect()">上一页</el-button><el-button :disabled="inspectionPage*20>=inspectionTotal||inspecting" @click="inspectionPage++;inspect()">下一页</el-button><span> 第{{inspectionPage}}页，共{{inspectionTotal}}篇</span><OperationsReport ref="inspectReport"/><el-divider content-position="left">外观发布历史</el-divider><el-table :data="history"><el-table-column prop="releaseId" label="版本" width="90"/><el-table-column prop="themeVersion" label="资源版本"/><el-table-column prop="createBy" label="发布人"/><el-table-column prop="createTime" label="时间"/><el-table-column label="操作"><template #default="s"><el-button v-if="can('publish')" link type="primary" :disabled="busy" @click="publish(s.row.releaseId)">恢复为新发布版</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="loadHistory"/>
<el-dialog v-model="previewOpen" title="外观草稿预览 · 未发布" width="95%" append-to-body destroy-on-close @closed="clearPreview"><iframe v-if="previewHTML" :srcdoc="previewHTML" sandbox="" referrerpolicy="no-referrer" style="width:100%;height:75vh;border:0" title="外观草稿预览"/></el-dialog>
</div></template>
<script setup>
import {ref,reactive,onMounted,onBeforeUnmount,onDeactivated} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import auth from '@/plugins/auth'
import AssetPicker from '../components/AssetPicker.vue'
import OperationsReport from '../components/OperationsReport.vue'
import {privateImage} from '@/api/cms/content'
const cfg=ref(),version=ref(0),history=ref([]),total=ref(0),loading=ref(false),busy=ref(false),previewOpen=ref(false),previewHTML=ref(''),pg=reactive({pageNum:1,pageSize:10}),kinds={PRODUCT:'产品',ARTICLE:'文章',PAGE:'单页'}
const canInspect=auth.hasPermiAnd(['cms:site:query','cms:asset:query','cms:channel:query','cms:article:query','cms:product:query','cms:page:query'])
let inspectionEpoch=0;
const inspecting=ref(false),inspectReport=ref(),inspectionPage=ref(1),inspectionTotal=ref(0)
async function inspect(){if(inspecting.value)return;const ticket=++inspectionEpoch;inspecting.value=true;try{const r=await request({url:'/cms/site/inspect',params:{pageNum:inspectionPage.value,pageSize:20},timeout:60000});if(ticket!==inspectionEpoch||!inspectReport.value)return;inspectionTotal.value=r.data.total;const issues=[...r.data.issues,...r.data.rows.flatMap(x=>x.issues)];inspectReport.value.open('站点巡检结果',issues,`本页检查${r.data.rows.length}篇，问题/待核验${issues.length}项，跳过外链${r.data.externalLinksSkipped}条。${r.data.scope}`)}finally{if(ticket===inspectionEpoch)inspecting.value=false}}
const can=p=>auth.hasPermi('cms:site:'+p);let epoch=0,historyEpoch=0,previewEpoch=0;const urls=[]
function move(rows,i,d){const j=i+d;if(j>=0&&j<rows.length)[rows[i],rows[j]]=[rows[j],rows[i]]}
async function load(){const ticket=++epoch;loading.value=true;try{const r=await request({url:'/cms/site'});if(ticket===epoch){cfg.value={iconAssetId:0,fontScale:'standard',frameWidth:'normal',radius:'square',...r.data.config};cfg.value.fontScale||='standard';cfg.value.frameWidth||='normal';cfg.value.radius||='square';for(const n of cfg.value.navigation)n.placement||='header';version.value=r.data.version}}finally{if(ticket===epoch)loading.value=false}}
async function loadHistory(){const ticket=++historyEpoch;const r=await request({url:'/cms/site/history',params:{...pg}});if(ticket===historyEpoch){history.value=r.rows;total.value=r.total}}
async function save(){if(busy.value)return;busy.value=true;try{const body=JSON.parse(JSON.stringify(cfg.value));for(const n of body.navigation){if(n.contentId>0)n.url=''};await request({url:'/cms/site',method:'put',data:{version:version.value,config:body}});ElMessage.success('草稿已保存，线上外观未改变');await load()}finally{busy.value=false}}
async function publish(id){if(busy.value)return;try{await ElMessageBox.confirm(id?'将重新校验历史引用并发布为新版本，未保存修改不会保留。':'发布已保存的外观草稿，未保存修改不会进入线上。','发布确认');busy.value=true;await request({url:'/cms/site/publish',method:'post',data:{version:version.value,releaseId:id}});ElMessage.success('外观已发布');await Promise.all([load(),loadHistory()])}catch{}finally{busy.value=false}}
function clearPreview(){++previewEpoch;for(const u of urls)URL.revokeObjectURL(u);urls.length=0;previewHTML.value=''}
async function preview(){clearPreview();const ticket=previewEpoch;const r=await request({url:'/cms/site/preview'});if(ticket!==previewEpoch)return;const doc=new DOMParser().parseFromString(r.data.html,'text/html');for(const img of doc.querySelectorAll('img')){const m=/^\/media\/([1-9][0-9]*)$/.exec(img.getAttribute('src')||'');if(!m){img.remove();continue};try{const blob=await privateImage(Number(m[1]));if(ticket!==previewEpoch)return;const u=URL.createObjectURL(blob);urls.push(u);img.src=u}catch{img.remove()}};for(const link of doc.querySelectorAll('link[rel="stylesheet"]'))link.href=new URL(link.getAttribute('href'),location.origin).href;for(const a of doc.querySelectorAll('a'))a.removeAttribute('href');const csp=doc.createElement('meta');csp.httpEquiv='Content-Security-Policy';csp.content="default-src 'none'; img-src blob:; style-src 'unsafe-inline' "+location.origin+"; base-uri 'none'";doc.head.prepend(csp);if(ticket!==previewEpoch)return;previewHTML.value='<!doctype html>'+doc.documentElement.outerHTML;previewOpen.value=true}
function cleanup(){++inspectionEpoch;inspectReport.value?.close();inspecting.value=false;++epoch;++historyEpoch;previewOpen.value=false;clearPreview()}
onMounted(()=>Promise.all([load(),loadHistory()]));onBeforeUnmount(cleanup);onDeactivated(cleanup)
</script><style scoped>.banner{border:1px solid #ddd;padding:12px;margin:10px 0;display:flex;gap:10px;align-items:center;flex-wrap:wrap}.banner>.el-input{width:220px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}</style>
